from __future__ import annotations
import argparse,csv,sqlite3,subprocess,sys
from pathlib import Path
TICKETS=[("SEC-102","security","MFA prompt loop for workforce portal","auth-log-77","MFA failed for 14 users","Clock drift of eleven minutes caused challenge expiry."),("ACC-104","access","Contractor role lost after renewal","api-log-122","Eight active accounts denied","Rotation job retained an expired access key."),("SEC-109","security","Endpoint alert reports unusual token reuse","endpoint-55","One host generated out-of-window requests","A stale token kept a broader-than-required scope."),("DAT-203","data","Daily warehouse load omitted one partition","load-log-203","One sales partition is absent","Late source watermark caused partition selection to close early."),("PERF-207","performance","Dashboard response exceeds target after deploy","perf-log-207","P95 rose from 0.8 s to 2.6 s","Unbounded join expanded the dashboard query plan."),("DAT-212","data","Duplicate customer dimension keys in export","export-log-212","Three duplicate keys reached the extract","Retry replay inserted the same batch twice."),("GEN-299","general","Request for a routine status update","ticket-log-299","No service impact reported","No technical root cause required.")]
def pdf(path):
 d=b"BT /F1 11 Tf 48 748 Td (ESCALATION EVIDENCE POLICY) Tj 0 -18 Td (Phase 1 review requires source_ref and impact evidence.) Tj 0 -18 Td (A rejection is expected until root_cause is supplied from the source notes.) Tj 0 -18 Td (Phase 2 approval requires all three evidence fields and a matching ticket category.) Tj ET";objs=[b"<< /Type /Catalog /Pages 2 0 R >>",b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",b"<< /Length "+str(len(d)).encode()+b" >>\nstream\n"+d+b"\nendstream"];o=bytearray(b"%PDF-1.4\n");off=[0]
 for i,x in enumerate(objs,1):off.append(len(o));o.extend(f"{i} 0 obj\n".encode()+x+b"\nendobj\n")
 pos=len(o);o.extend(f"xref\n0 {len(off)}\n0000000000 65535 f \n".encode());[o.extend(f"{n:010d} 00000 n \n".encode()) for n in off[1:]];o.extend(f"trailer\n<< /Size {len(off)} /Root 1 0 R >>\nstartxref\n{pos}\n%%EOF\n".encode());path.write_bytes(o)
def main():
 p=argparse.ArgumentParser();p.add_argument("--workspace",required=True);p.add_argument("--source-dir",required=True);p.add_argument("--start-service",action="store_true");p.add_argument("--open-browser",action="store_true");a=p.parse_args();root=Path(a.workspace).expanduser().resolve()/"ticket_hub";root.mkdir(parents=True,exist_ok=True);(root/"out").mkdir(exist_ok=True);db=sqlite3.connect(root/"tickets.db");db.executescript("CREATE TABLE tickets(ticket_id TEXT PRIMARY KEY,category TEXT,summary TEXT,status TEXT DEFAULT 'OPEN',assignee TEXT DEFAULT '',source_ref TEXT,impact TEXT,root_cause_hint TEXT,evidence_json TEXT DEFAULT '{}');CREATE TABLE approvals(ticket_id TEXT PRIMARY KEY,preview_id TEXT,evidence_hash TEXT,status TEXT);CREATE TABLE reviews(preview_id TEXT PRIMARY KEY,ticket_id TEXT,decision TEXT,missing_json TEXT);")
 db.executemany("INSERT INTO tickets(ticket_id,category,summary,source_ref,impact,root_cause_hint) VALUES(?,?,?,?,?,?)",TICKETS);db.commit();db.close()
 with (root/"ticket_sources.csv").open("w",encoding="utf-8",newline="") as f:w=csv.writer(f);w.writerow(["ticket_id","category","summary","source_ref","impact","root_cause_hint"]);w.writerows(TICKETS)
 (root/"workflow_events.jsonl").touch(exist_ok=True)
 pdf(root/"escalation_policy.pdf")
 if a.start_service:
  log=(root/"ticket_service.log").open("ab",buffering=0);subprocess.Popen([sys.executable,str(Path(a.source_dir)/"ticket_service.py"),"--root",str(root)],stdout=log,stderr=log,start_new_session=True);log.close()
 if a.open_browser:subprocess.Popen(["google-chrome","http://127.0.0.1:18118/"],start_new_session=True)
if __name__=="__main__":main()
